param(
 [string]$DispatcherPath=(Join-Path $PSScriptRoot '..\launch_paper_text_multiseed_smoke_r13.ps1'),
 [string]$SupervisorPath=(Join-Path $PSScriptRoot '..\supervise_paper_text_multiseed_smoke_r13.ps1'),
 [string]$RunnerPath=(Join-Path $PSScriptRoot '..\run_paper_text_multiseed_smoke_r13.sh'),
 [string]$HelperPath=(Join-Path $PSScriptRoot '..\r13_exactly_once_helpers.ps1')
)
$ErrorActionPreference='Stop'
$dispatcher=Get-Content -LiteralPath (Resolve-Path -LiteralPath $DispatcherPath) -Raw;$supervisor=Get-Content -LiteralPath (Resolve-Path -LiteralPath $SupervisorPath) -Raw;$runner=Get-Content -LiteralPath (Resolve-Path -LiteralPath $RunnerPath) -Raw;$helper=Get-Content -LiteralPath (Resolve-Path -LiteralPath $HelperPath) -Raw
function Assert-Contains([string]$Text,[string]$Needle,[string]$Label){if(!$Text.Contains($Needle)){throw "${Label} is missing: $Needle"}}
foreach($pair in @(@($dispatcher,'paper-text-v1-multiseed-cap128-r13-20260830'),@($supervisor,'paper-text-v1-multiseed-cap128-r13-20260830'),@($runner,'paper-text-v1-multiseed-cap128-r13-20260830'),@($runner,'PAPER_TEXT_STAGE3_GLOBAL_NORM_CLIP_V1'),@($runner,'--seeds 42 43'),@($runner,'--cap 128'),@($runner,'--stage3-gradient-clip-norm 1.0'),@($supervisor,'child_kind=''wsl.exe'''),@($supervisor,'DeleteTask($TaskName,0)'))){Assert-Contains $pair[0] $pair[1] 'r13 source'}
if($dispatcher-match'AllowStartOnDemand' -or $dispatcher-notmatch'AllowDemandStart=\$true'){throw 'r13 dispatcher does not use the PS5.1 COM AllowDemandStart property'}
if($dispatcher-match'--resume|--retry' -or $supervisor-match'--resume|--retry' -or $runner-match'--resume|--retry'){throw 'r13 sources contain retry or resume'}
if($dispatcher-match'r12'-or$supervisor-match'r12'-or$runner-match'r12'){throw 'r13 sources reference r12 identity'}
if(([regex]::Matches($runner,'paper_faithful\.training\.cli multi-seed-pilot')).Count-ne1){throw 'r13 runner must invoke multi-seed-pilot exactly once'}
if(([regex]::Matches($supervisor,'AddSeconds\(60\)')).Count-ne2-or$supervisor-notmatch'Atomic WSL exit evidence absent after Windows host exit'-or$supervisor-notmatch'Windows WSL host remained after atomic exit evidence'){throw 'r13 terminal barrier lost its bounded mismatch grace'}
foreach($needle in @('confirmation.seeds','confirmation.expected_children','cache_validator_log.sha256-ne[string]$gate.cache_gate.validator_v2_log_sha256','windows_host_exit_code=$terminalBarrier.windows_host_exit_code','windows_host_gone_at=$terminalBarrier.host_gone_at')){Assert-Contains $supervisor $needle 'r13 supervisor binding'}
foreach($needle in @('Assert-R13OwnedLifecycleAvailable $lifecycle $dispatch','Open-R13PermanentMarker $dispatch',"Exception.Data.Contains('r13_exit_code')")){Assert-Contains $dispatcher $needle 'r13 dispatcher refusal binding'}
foreach($needle in @('Assert-R13OwnedLifecycleAvailable $lifecycle $attemptMarker','Assert-R13BoundDispatchRecord $dispatchMarker $dispatchLifecycle','Open-R13PermanentMarker $attemptMarker',"Exception.Data.Contains('r13_exit_code')")){Assert-Contains $supervisor $needle 'r13 supervisor refusal/dispatch binding'}
foreach($needle in @("Data['r13_exit_code'] = 91",'[IO.FileMode]::CreateNew','[IO.FileShare]::None','lifecycle belongs to an invocation that consumed its permanent marker','exactly one bound dispatch_created event','dispatch marker is not exclusively held','Assert-R13GpuComputeProbeResult','Assert-R13GpuComputeIdle','set -o pipefail; nvidia-smi --query-compute-apps=pid')){Assert-Contains $helper $needle 'r13 exactly-once/resource helper'}
$launcherBindingsAt=$dispatcher.IndexOf('foreach($b in @($gate.source_bindings))',[StringComparison]::Ordinal);$launcherHelperAt=$dispatcher.IndexOf('. $helperPath',[StringComparison]::Ordinal);$supervisorBindingsAt=$supervisor.IndexOf('foreach($b in @($gate.source_bindings))',[StringComparison]::Ordinal);$supervisorHelperAt=$supervisor.IndexOf('. $helperPath',[StringComparison]::Ordinal)
if($launcherBindingsAt-lt0-or$launcherHelperAt-le$launcherBindingsAt-or$supervisorBindingsAt-lt0-or$supervisorHelperAt-le$supervisorBindingsAt){throw 'r13 helper executes before source binding lock'}
if($dispatcher.Contains('@($dispatch,$lifecycle')-or$supervisor.Contains('@($attemptMarker,$lifecycle')){throw 'r13 permanent marker remains in a generic namespace check'}
$recordAt=$supervisor.IndexOf('Assert-R13BoundDispatchRecord',[StringComparison]::Ordinal);$attemptAt=$supervisor.IndexOf('Open-R13PermanentMarker $attemptMarker',[StringComparison]::Ordinal);$processAt=$supervisor.IndexOf('Start-Process -FilePath "$env:SystemRoot\System32\wsl.exe"',[StringComparison]::Ordinal)
if($recordAt-lt0-or$attemptAt-le$recordAt-or$processAt-le$attemptAt){throw 'r13 dispatch/attempt/workload ordering failed'}
$dispatcherGpuAt=$dispatcher.IndexOf("Assert-R13GpuComputeIdle 'dispatcher-pre-dispatch'",[StringComparison]::Ordinal);$dispatcherMarkerAt=$dispatcher.IndexOf("Open-R13PermanentMarker `$dispatch 'dispatch'",[StringComparison]::Ordinal);$supervisorGpuAt=$supervisor.IndexOf("Assert-R13GpuComputeIdle 'supervisor-pre-workload';`$child=Start-Process",[StringComparison]::Ordinal)
if($dispatcherGpuAt-lt0-or$dispatcherMarkerAt-le$dispatcherGpuAt-or$supervisorGpuAt-lt0-or$processAt-le$supervisorGpuAt){throw 'r13 live GPU compute-process refusal ordering failed'}
[ordered]@{status='pass';pilot_launched=$false;fresh_r13_identity=$true;no_retry_or_resume=$true;dual_create_new_exclusive_markers=$true;helper_hash_locked_before_execution=$true;marker_specific_lifecycle_race_mapping=$true;second_invocation_exit_code=91;bound_dispatch_required_before_attempt=$true;live_gpu_compute_process_refusal=$true;dispatcher_gpu_check_before_dispatch=$true;supervisor_gpu_check_immediately_before_workload=$true;foreground_wsl=$true;bounded_terminal_barrier=$true;exact_confirmation_and_cache_bindings=$true;stage3_protocol='PAPER_TEXT_STAGE3_GLOBAL_NORM_CLIP_V1'}|ConvertTo-Json -Compress
